"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1000-01-01:1":{"b": ["Ragusa (Dubrovnik) اور جنوبی Dalmaçya کے شہروں نے Orseolo کی بیعت کی", "6121e2e9"], "d": ["Orseolo کی Dalmaçya مہم میں Ragusa نے، Dalmaçya کے شہروں میں سب سے جنوبی ہونے کے ناطے، اپنے سفیروں اور آرچ بشپ کے ساتھ San Massimo کے چھوٹے جزیرے پر doge کی فوج کا استقبال کیا اور ونیس (Venedik) سے وفاداری پیش کی۔", "638f8cad"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1013-01-01:0":{"b": ["محمود نے لاہور ہندو شاہیوں سے لیا؛ لاہور غزنویوں کا سب سے پسندیدہ شہر بن گیا", "37ab3445"], "d": ["لاہور، 991 کے بعد ہندو شاہیوں کے ہاتھ میں رہنے کے بعد، 1013-1014 میں غزنوی محمود کے قبضے میں آیا؛ محمود نے لاہور کا قلعہ مضبوط کیا اور خراسان سے لائے گئے ترک اور تاجک سپاہیوں پر مشتمل چھاؤنی قائم کی۔ غزنویوں کے آزادی کھو دینے پر (1157 کے بعد) لاہور مشرق میں باقی رہنے والے حصے کا مرکز بنا۔", "90b6f385"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1015-01-01:0":{"b": ["بادشاہ Robert II نے تیرہ سال چلنے والی جنگ کے بعد Burgonya ڈچی کو فرانسیسی تاج میں شامل کر لیا", "257ea2c6"], "d": ["ڈیوک Henry کی 1002 میں موت کے بعد Burgonya ڈچی کے لیے جنگ چھڑ گئی؛ فرانس کے بادشاہ Robert II نے Burgonya کے کاؤنٹ Otto-William کی مزاحمت کے باوجود تیرہ سال چلنے والی جنگ کے آخر میں 1015 میں ڈچی کو بادشاہت میں شامل کیا اور اپنے بیٹے Henry (بعد کے Henri اول) کو دے دیا۔", "9b353b9c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:0":{"b": ["Basileios II Ohri میں داخل ہوا: مغربی بلغاری دارالحکومت بازنطین کے ہاتھ آ گیا", "05fe0972"], "d": ["Samuil کی موت کے بعد چار سال مزاحمت کرنے والے بلغاری خاندان نے 1018 کے آغاز میں Ohri کے دروازوں پر Basileios II کے آگے ہتھیار ڈال دیے۔ Ohri کی آرچ بشپی بازنطینی حکومت کے تحت سلاوی مسیحیت کے مرکز کے طور پر قائم رہی۔", "b6ac5adb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-01-01:1":{"b": ["پولینڈ کے بادشاہ Bolesław Chrobry نے جرمن اور Pecheneg حمایت سے Kiev لے لیا", "3e44ca65"], "d": ["اگست 1018 میں Bolesław نے جرمن اور Pecheneg افواج کے ساتھ Kiev پر قبضہ کیا؛ Buh دریا پر Yaroslav کو شکست دینے والے Bolesław نے اپنے داماد Sviatopolk کو تخت پر بٹھایا۔ Yaroslav صرف 1019 میں Kiev واپس لے سکا۔", "33889946"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-05-20:0":{"b": ["محمود متھرا (Muttra) شہر پر قابض ہوا", "78547f01"], "d": ["قنوج کی مہم کے دوران غزنوی فوج دہلی اور آگرہ کے راستے کے درمیان واقع متھرا شہر پر قابض ہوئی (409/1018)۔", "bb198817"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1018-12-20:0":{"b": ["محمود نے قنوج (Kanyakubja) فتح کیا", "258b5624"], "d": ["محمود 13 جمادی الاول 409 (27 ستمبر 1018) کو غزنہ سے روانہ ہو کر بارہویں ہندوستانی مہم پر نکلا؛ Sarsava قلعہ، Baran کے راجہ کی اطاعت اور متھرا کے بعد اصل ہدف قنوج 8 شعبان 409 (20 دسمبر 1018) کو فتح ہوا۔", "5952deed"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1028-01-01:0":{"b": ["Knud den Store ناروے میں بادشاہ قرار دیا گیا؛ Olav Haraldsson فرار ہوا", "89688331"], "d": ["Knud نے 1028 میں پچاس جہازوں کے بیڑے کے ساتھ ناروے آ کر Øretinget میں ناروے کے بادشاہ کے طور پر تحسین پائی؛ بادشاہ Olav Haraldsson II پہلے سویڈن، پھر روس (Gardarike) بھاگ گیا۔", "35460867"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1030-01-01:0":{"b": ["Aversa کاؤنٹی قائم ہوئی: Rainulf Drengot نارمن کاؤنٹ بنا", "ec99b57a"], "d": ["1030 میں Napoli کے ڈیوک Sergius کے Rainulf کو Aversa قلعے میں بسانے سے نارمنوں کو پہلی بار مستقل اڈہ ملا اور جنوبی اٹلی کی منظم فتح شروع ہوئی۔", "8d2a9071"]},
