"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1057-03-10:0":{"b": ["زیری امیر معز قیروان سے نکل کر مہدیہ چلا گیا؛ قیروان ہلالیوں کے ہاتھ میں چلا گیا", "becee655"], "d": ["بنو ہلال کے محاصرے پر معز بن بادیس 449 (1057) میں قیروان سے نکل کر مہدیہ چلا گیا جہاں اس کا بیٹا تمیم گورنر تھا؛ بے دفاع قیروان کو بدوؤں نے لوٹا اور جلا دیا۔", "7b6732bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1061-01-01:0":{"b": ["کاؤنٹ Roger نے Messina پر قبضہ کیا (1061)", "28b31d9a"], "d": ["Roger 1061 میں Messina کے گرد و نواح میں اترا اور شہر نسبتاً آسانی سے لے لیا؛ یوں سسلی کی نارمن فتح شروع ہوئی۔ TDV اس سال کو Messina کے لیے جانے کا سال بتاتا ہے۔", "d06afdbf"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:0":{"b": ["الپ ارسلان نے بازنطین کا Kars فتح کیا؛ جارجیائی بادشاہ سلجوقیوں کا تابع ہوا", "25994288"], "d": ["الپ ارسلان 1067 میں دوبارہ بازنطین اور جارجیا کی سرحدوں پر نمودار ہوا؛ بازنطین کا Kars فتح ہوا اور جارجیائی بادشاہ سلجوقیوں کا تابع ہو گیا۔", "5395feca"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1067-01-01:1":{"b": ["الپ ارسلان نے قیصریہ (Kayseri) لے لیا", "c40df514"], "d": ["سلجوقی سلطان الپ ارسلان کے دور میں ترکوں نے 1065 میں Ani اور 1067 میں Kayseri پر قبضہ کیا؛ بازنطین نے Kapadokya کے دروازے کھو دیے۔", "fbeb3963"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1071-01-01:0":{"b": ["Catania نارمنوں کے ہاتھ آ گیا (1071)", "21617f1b"], "d": ["Bari کا محاصرہ جاری تھا کہ 1071 میں Catania شہر میں غداری سے نارمنوں کے ہاتھ آ گیا؛ مگر شہر بعد میں کھو گیا اور تقریباً دس سال بعد مستقل طور پر لیا گیا۔", "3d49a9a2"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-01-01:0":{"b": ["Mazara نارمنوں کے ہاتھ آ گیا (1072)", "e7cb9667"], "d": ["پالرمو کے لیے جانے کے سال 1072 میں Mazara بھی فتح ہوا؛ بعد کے برسوں میں وہاں قلعہ بنا کر شمالی افریقہ سے آنے والے حملے کا مقابلہ کیا گیا (1075)۔", "95450106"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1072-12-15:0":{"b": ["نصر دوم نے الپ ارسلان کی موت پر ترمذ لیا، پھر بلخ پر چڑھ کر اسے بھی قبضے میں لیا", "7747ccc9"], "d": ["الپ ارسلان کی ماوراء النہر کی مہم میں موت پر مغربی قراخانی شمس الملک نصر دوم نے ربیع الثانی 465 (دسمبر 1072) میں ترمذ لیا، پھر بلخ پر چڑھ کر اسے بھی قبضے میں لیا؛ سلجوقی-قراخانی کشمکش ملک شاہ کے دور میں جاری رہی۔", "1ba5253a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1073-01-01:0":{"b": ["Amalfi نے Salerno کے دباؤ کے خلاف Roberto il Guiscardo سے رجوع کیا؛ نارمنوں نے شہر پر قبضہ کر لیا اور آزادی ختم ہو گئی...", "3d375631"], "d": ["Amalfi نے Salerno کے دباؤ کے خلاف Roberto il Guiscardo سے رجوع کیا؛ نارمنوں نے شہر پر قبضہ کر لیا اور آزادی ختم ہو گئی۔", "be93237a"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1075-08-16:0":{"b": ["ملک شاہ کے امیر ساوتگین نے اران پر قبضہ کر لیا؛ شدادیوں کی گنجہ شاخ ختم ہو گئی", "e031fc26"], "d": ["شدادی فضل سوم کے دور میں سلطان ملک شاہ کے امیروں میں سے ساوتگین نے اران پر قبضہ کر لیا (468/1075-76)؛ یہ علاقہ سلجوقی انتظام میں آ گیا اور شدادیوں کی گنجہ شاخ ختم ہو گئی۔", "b39c17bd"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1076-01-01:0":{"b": ["Salerno، Robert Guiscard کے ہاتھ آ گیا؛ لومبارڈ سالیرنو سلطنتِ امارت ختم ہو گئی", "c678238f"], "d": ["طویل مزاحمت کے بعد Salerno دسمبر 1076 میں Robert Guiscard کے حوالے ہو گیا؛ شہزادہ Gisulf دوم جلاوطن ہو کر پاپائی دربار میں چلا گیا۔ Guiscard نے Salerno کو اپنی ڈچی کا دارالحکومت بنایا۔", "705fecee"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-01-01:0":{"b": ["Roger نے اپنے بحری بیڑے سے Trapani لے لیا", "2b0b3d98"], "d": ["بحری بیڑا بنانے والے Roger نے 1077 میں جنگی سرگرمیاں تیز کر دیں، Trapani اور پھر Castronovo پر قبضہ کیا۔", "6e482ca5"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1077-07-25:0":{"b": ["یوسف بن تاشفین نے طنجہ پر قبضہ کیا", "aa4376c4"], "d": ["مرابطی امیر یوسف بن تاشفین نے مغربِ اقصیٰ کے اہم ساحلی شہر طنجہ کو 470 (1077-78) میں لے لیا۔", "94bf21ec"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1081-01-01:0":{"b": ["Robert Guiscard Valona میں اترا اور Corfu لے لیا", "d5e43c94"], "d": ["1081 میں Guiscard اپنے بیڑے کے ساتھ Valona (اولونیا) کی طرف بڑھا، Corfu لے لیا اور 1082 میں Durazzo پر قبضہ کیا؛ قسطنطنیہ کی طرف پیش قدمی روم میں Gregorius VII کی مدد کے لیے بلائے جانے پر ادھوری رہ گئی۔", "f805ca31"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1082-01-01:0":{"b": ["اناطولیہ کے سلجوقی بانی سلیمان شاہ اول نے طرسوس فتح کیا", "93d6092f"], "d": ["سلیمان شاہ اول نے 475/1082 میں طرسوس فتح کیا؛ شہر 490/1097 میں صلیبیوں نے لے لیا اور پھر صلیبیوں، بازنطینیوں اور خطے کے آرمینیوں کے درمیان ہاتھ بدلتا رہا۔", "912208e8"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:1084-03-24:0":{"b": ["روم Henry IV کے حوالے ہو گیا؛ انٹی پوپ Clemens III (Guibert) تخت نشین ہوا، Henry نے شاہنشاہی تاج پہنا، Gregorius روم سے فرار ہو گیا", "311cfeb4"], "d": ["1081 میں اٹلی میں اترنے والے Henry کے سامنے رومیوں نے شہر حوالے کر دیا؛ راویناکے آرچ بشپ Guibert کو 24 مارچ 1084 کو Clemens III کے نام سے پوپ قرار دیا گیا اور Henry کو حریف پوپ نے شہنشاہ کا تاج پہنایا۔ تیرہ کارڈینلوں کے چھوڑ جانے پر Gregorius VII کو روم سے فرار ہونا پڑا؛ اس نے نارمنوں کی حمایت پر بھروسا کیا۔", "996d4e46"]},
